<template><section class="works-trash"><header><h2>系统回收站 · 本应用删除记录</h2><button @click="load">刷新</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="!items.length">没有可恢复的记录。系统中已清空或移走的项目不会保留为可恢复记录。</p><table><thead><tr><th>原路径</th><th>删除时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.originalPath||item.original }}</td><td>{{ item.deletedAt }}</td><td><button :disabled="busy" @click="restore(item)">恢复</button></td></tr></tbody></table></section></template>
<script>
import { api,json } from './api.js';
export default {data(){return{items:[],error:'',busy:false}},mounted(){this.load()},methods:{async load(){try{this.items=await api('works/trash');this.error=''}catch(e){this.error=e.message}},async restore(item){this.busy=true;let name='',createParents=false;try{for(;;){try{await api('works/trash/restore',{},json({id:item.id,name,createParents}));await this.load();return}catch(e){if(e.data?.code==='RESTORE_PARENT_CONFIRMATION'){if(!window.confirm('原父目录不存在，是否重建父目录后恢复？'))return;createParents=true;continue}if(e.data?.code==='RESTORE_NAME_CONFLICT'){name=window.prompt('原名称已存在，请输入新的文件名；取消将保留回收内容。','');if(!name)return;continue}throw e}}}catch(e){this.error=e.message}finally{this.busy=false}}}}</script>
<style scoped>.works-trash{position:fixed;inset:0;padding:20px;background:#fff;color:#222;overflow:auto;font:14px system-ui}.works-trash header{position:static;background:transparent;color:inherit;display:flex;justify-content:space-between}.works-trash table{width:100%;border-collapse:collapse}.works-trash td,.works-trash th{text-align:left;border-bottom:1px solid #ddd;padding:10px;overflow-wrap:anywhere}.works-trash button{cursor:pointer;padding:6px 12px}</style>
